const items = $input.all();

return items.map(item => {
  const ticket = item.json;

  let email = ticket.customer_email;

  if (typeof email === 'string') {
    email = email.trim().toLowerCase();

    if (email.endsWith('@gmail.com')) {
      const [localPart, domain] = email.split('@');
      const normalizedLocalPart = localPart.split('+')[0];

      email = `${normalizedLocalPart}@${domain}`;
    }
  }

  return {
    json: {
      ...ticket,
      normalized_customer_email: email ?? null
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const classification =
    data.output?.[0]?.content?.[0]?.text;

  if (
    !classification ||
    !classification.intent ||
    typeof classification.confidence !== 'number'
  ) {
    return {
      json: {
        ...data,
        intent: null,
        confidence: null,
        classification_error: "Invalid classifier output"
      }
    };
  }

  return {
    json: {
      ...data,
      intent: classification.intent,
      confidence: classification.confidence,
      classification_error: null
    }
  };
});

const items = $input.all();

return items.map(item => {
  const ticket = item.json;

  const subscriptions = Array.isArray(ticket.subscriptions)
    ? ticket.subscriptions
    : [];

  const matchingSubscriptions = subscriptions.filter(
    sub => sub.product === ticket.product
  );

  const activeMatchingSubscriptions = matchingSubscriptions.filter(
    sub => sub.status === 'active'
  );

  let actionStatus = 'not_executed';
  let reason = null;
  let subscriptionId = null;

  if (activeMatchingSubscriptions.length === 1) {
    actionStatus = 'simulated_success';
    subscriptionId = activeMatchingSubscriptions[0].id;
  } 
  else if (activeMatchingSubscriptions.length === 0) {
    actionStatus = 'not_executed';
    reason = 'No active matching subscription found';
  } 
  else {
    actionStatus = 'requires_review';
    reason = 'Multiple active matching subscriptions found';
  }

  return {
    json: {
      ...ticket,
      matching_subscription_count: matchingSubscriptions.length,
      action_type: 'cancellation',
      action_status: actionStatus,
      details: {
        reason: reason,
        subscription_id: subscriptionId,
        active_matching_subscription_count: activeMatchingSubscriptions.length
      }
    }
  };
});

