  let billingProvider = null;

  if (activeMatchingSubscriptions.length === 1) {
    const subscription = activeMatchingSubscriptions[0];

    actionStatus = 'simulated_success';
    subscriptionId = subscription.id;
    billingProvider = subscription.billing_provider ?? null;
  }
  else if (activeMatchingSubscriptions.length === 0) {
    actionStatus = 'not_executed';
    reason = 'No active matching subscription found';
  }
  else {
    actionStatus = 'requires_review';
    reason = 'Multiple active matching subscriptions found';
