const items = $input.all();

return items.map(item => {
  const ticket = item.json;

  const message = String(ticket.message ?? '').toLowerCase();

  let matchedTopic = null;
  let responseContext = null;

  if (
    message.includes('freezing') ||
    message.includes('freeze')
  ) {
    matchedTopic = 'freezing';

    responseContext =
      'Ask the customer to update the app, restart the device, and retry.';
  }
  else if (
    message.includes('login')
  ) {
    matchedTopic = 'login';

    responseContext =
      'Ask the customer to verify the account email and reset the password.';
  }

  if (matchedTopic) {
    return {
      json: {
        ...ticket,

        matching_subscription_count: 0,

        action_type: 'technical_guidance',

        action_status: 'simulated_success',

        details: {
          reason: null,
          knowledge_base_topic: matchedTopic,
          response_context: responseContext
        }
      }
    };
  }

  return {
    json: {
      ...ticket,

      matching_subscription_count: 0,

      action_type: 'manual_review',

      action_status: 'requires_review',

      details: {
        reason: 'No matching technical knowledge-base entry found',
        knowledge_base_topic: null,
        response_context: null
      }
    }
